/**
 * Live presence on the site: three teammates in a support handbook, simulated. Pixel reads and selects, Comet writes a
 * line and fixes it, Sprout changes the refund window. Click someone in the stack, or the pill of anyone out of view,
 * to follow them. A premium element: this example is free to read, the element installs with
 * FoundKeep Pro.
 *
 * In an app the people come from your realtime layer (their pointer, selection and caret as places in the text);
 * here a small script plays them, on a clock that stops while the example is out of sight.
 */
import { useEffect, useRef, useState } from "react";
import { LivePresence, type LivePresencePerson, type LivePresencePlace } from "@/components/application/premium/live-presence";

type Doing = Pick<LivePresencePerson, "pointer" | "selection" | "caret" | "typing">;
const TEAM: LivePresencePerson[] = [
  { id: "pixel", name: "Pixel", color: "#2563eb", darkColor: "#3b74f0" },
  { id: "comet", name: "Comet", color: "#c2410c", darkColor: "#c9531c" },
  { id: "sprout", name: "Sprout", color: "#15803d", darkColor: "#1d8f48" },
  { id: "pebble", name: "Pebble", color: "#7c3aed", away: true },
  { id: "moss", name: "Moss", color: "#0f766e", away: true },
];
const at = (anchor: string, offset: number | "end" = 0, dx = 0, dy = 0): LivePresencePlace => ({ anchor, offset, dx, dy });
const rand = (a: number, b: number) => a + Math.random() * (b - a);
/** About how long a pointer takes to get somewhere, and a selection to grow under it. */
const GLIDE = 700, DRAG = 600;

export default function LivePresenceDemo() {
  const root = useRef<HTMLDivElement>(null);
  const [doing, setDoing] = useState<Record<string, Doing>>({
    pixel: { pointer: at("lede", 52, 2, 4) },
    comet: { pointer: at("reply", 30, 0, 4) },
    sprout: { pointer: at("h-refund", 8, 4, 6) },
  });
  const [slot, setSlot] = useState("");
  const [days, setDays] = useState("within 30 days");

  useEffect(() => {
    let alive = true, running = true, clock = 0, last = performance.now(), raf = 0;
    const waits: { t: number; done: () => void }[] = [];
    const tick = (now: number) => {
      if (running) clock += Math.min(50, now - last);
      last = now;
      for (let k = waits.length - 1; k >= 0; k--) if (waits[k]!.t <= clock) waits.splice(k, 1)[0]!.done();
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    // The scripts wait on this clock, which rests while nobody can see the example.
    const wait = (ms: number) => new Promise<void>((done) => alive && waits.push({ t: clock + ms, done }));
    let onScreen = true;
    const sync = () => (running = onScreen && !document.hidden);
    const io = new IntersectionObserver((entries) => {
      onScreen = entries[entries.length - 1]!.isIntersecting;
      sync();
    });
    if (root.current) io.observe(root.current);
    document.addEventListener("visibilitychange", sync);

    const set = (id: string, patch: Doing) => alive && setDoing((d) => ({ ...d, [id]: { ...d[id], ...patch } }));
    async function select(id: string, anchor: string, hold: number) {
      set(id, { pointer: at(anchor, 0, -1, 2), selection: { from: at(anchor, 0), to: at(anchor, "end") } });
      await wait(GLIDE + DRAG + hold);
    }
    async function type(id: string, write: (f: (text: string) => string) => void, anchor: string, text: string) {
      set(id, { caret: at(anchor, "end"), typing: true, pointer: at(anchor, "end", 5, 6) });
      for (const ch of text) {
        write((t) => t + ch);
        await wait(ch === " " ? rand(70, 160) : /[.,]/.test(ch) ? rand(180, 320) : rand(45, 120));
      }
      set(id, { typing: false });
    }
    async function erase(id: string, write: (f: (text: string) => string) => void, anchor: string, n: number) {
      set(id, { caret: at(anchor, "end"), typing: true });
      for (let k = 0; k < n; k++) {
        write((t) => t.slice(0, -1));
        await wait(rand(28, 55));
      }
      set(id, { typing: false });
    }
    const writeSlot = (f: (t: string) => string) => alive && setSlot(f);
    const writeDays = (f: (t: string) => string) => alive && setDays(f);

    async function pixel() {
      await wait(600);
      while (alive) {
        await select("pixel", "shadow", 2200);
        set("pixel", { selection: null, pointer: at("friday", 38, 0, 6) });
        await wait(GLIDE + 1600);
        await select("pixel", "read", 2400);
        set("pixel", { selection: null, pointer: at("lede", 96, 4, 6) });
        await wait(GLIDE + 2600);
        set("pixel", { pointer: at("h-week", 9, 2, 4) });
        await wait(GLIDE + 1800);
      }
    }
    async function comet() {
      await wait(1200);
      const lines: [string, string | null, string | null][] = [
        ["If they wrote in another language, answer in it when you can.", "answer in it when you can.", "reply in that language if you can."],
        ["Never close a ticket in the same message that answers it.", null, null],
        ["Link the help article, and still answer the question in your own words.", "and still answer", "but answer"],
      ];
      let n = 0, written = "";
      const write = (f: (t: string) => string) => {
        written = f(written);
        writeSlot(() => written);
      };
      while (alive) {
        const [first, cut, fix] = lines[n++ % lines.length]!;
        set("comet", { pointer: at("slot", "end", 5, 6) });
        await wait(GLIDE + 300);
        await type("comet", write, "slot", first);
        await wait(1400);
        if (cut && fix) {
          const tail = first.slice(first.indexOf(cut) + cut.length);
          await erase("comet", write, "slot", cut.length + tail.length);
          await wait(500);
          await type("comet", write, "slot", fix + tail);
        }
        set("comet", { caret: null });
        await wait(1200);
        set("comet", { pointer: at("h-answer", 12, 6, 8) });
        await wait(GLIDE + 3200);
        set("comet", { pointer: at("reply", 64, 0, 6) });
        await wait(GLIDE + 2600);
        set("comet", { pointer: at("slot", "end", 5, 6) });
        await wait(GLIDE);
        await erase("comet", write, "slot", written.length);
        set("comet", { caret: null });
        await wait(600);
      }
    }
    async function sprout() {
      await wait(900);
      let current = "within 30 days";
      const write = (f: (t: string) => string) => {
        current = f(current);
        writeDays(() => current);
      };
      while (alive) {
        await select("sprout", "days", 900);
        const next = current.includes("30") ? "within 45 days" : "within 30 days";
        set("sprout", { selection: null });
        write(() => "");
        await type("sprout", write, "days", next);
        set("sprout", { caret: null });
        await wait(1800);
        await select("sprout", "credit", 2600);
        set("sprout", { selection: null, pointer: at("h-close", 6, 2, 6) });
        await wait(GLIDE + 900);
        await select("sprout", "close", 2600);
        set("sprout", { selection: null, pointer: at("h-refund", 14, 6, 8) });
        await wait(GLIDE + 2200);
      }
    }
    void pixel();
    void comet();
    void sprout();
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      waits.length = 0;
      io.disconnect();
      document.removeEventListener("visibilitychange", sync);
    };
  }, []);

  const people = TEAM.map((person) => ({ ...person, ...doing[person.id] }));
  return (
    <div ref={root} style={{ width: "100%", height: 600 }}>
      <LivePresence title="Support handbook" folder="Team docs" people={people}>
        <h1>Support handbook</h1>
        <p data-anchor="lede">How we answer customers, from the first reply to closing the ticket. Read it before your first shift, and change it when you find a better way.</p>

        <h2 data-anchor="h-week">Your first week</h2>
        <p>
          <span data-anchor="shadow">Shadow two shifts before you take tickets on your own.</span> Sit with whoever is on the queue, read along, and ask why they chose each reply.
        </p>
        <p data-anchor="friday">By Friday you should have answered ten tickets, each one read by a teammate before it goes out.</p>
        <ul>
          <li>Set up three inbox views: new, waiting on us and waiting on them.</li>
          <li>
            <span data-anchor="read">Read the last month of refund tickets.</span>
          </li>
          <li>Join the on-call rota from your third week.</li>
        </ul>

        <h2 data-anchor="h-answer">Answering a ticket</h2>
        <p data-anchor="reply">Reply within four working hours, even if the reply only says you are looking into it. Say what you will do next and when they will hear from you.</p>
        <p>
          Write the way you would talk to someone at the next desk: short sentences, no scripts, and their name once. <span data-anchor="slot">{slot}</span>
        </p>

        <h2 data-anchor="h-hand">When to hand over</h2>
        <p>Hand a ticket to engineering when you can reproduce a bug, or when two customers report the same thing on one day. Include the steps, what you expected and what happened.</p>
        <p>Send billing questions to the finance inbox, but stay on the thread, so nobody is passed around without a name.</p>

        <h2 data-anchor="h-refund">Refunds and credits</h2>
        <p>
          You can refund any order <span data-anchor="days">{days}</span> without asking anyone. After that, <span data-anchor="credit">offer a credit on the next invoice instead</span>, and note the reason on the account.
        </p>
        <p>For a large refund, ask a lead first. It is not a test of your judgement; it keeps one person from carrying a hard call alone.</p>

        <h2>Tone</h2>
        <p>Be warm and plain. Skip “unfortunately” and “please be advised”. If we got something wrong, say so in the first line.</p>

        <h2 data-anchor="h-close">Closing a ticket</h2>
        <p>
          Close a ticket when the customer confirms it is solved, or <span data-anchor="close">after three days without a reply</span>. Tag it with the part of the product it was about, so the weekly review can spot patterns.
        </p>
      </LivePresence>
    </div>
  );
}

